/**
 * @file main.c
 * @brief Chương trình chính STM32F469I-DISCO với 6 tác vụ trên nhân RTOS tiền định
 *        chuyển đổi từ tham-khao/main-freertos.c:
 *        1. vTaskLED1 (1000 ms chu kỳ)
 *        2. vTaskLED2 (400 ms chu kỳ)
 *        3. vTaskButton (quét nút USER PA0, chống rung 30 ms)
 *        4. vTaskLED3 (chờ hàng đợi từ nút bấm để đảo trạng thái)
 *        5. vTaskMonitor (nhịp tim LED4 PK3)
 *        6. vTaskLCD (quản lý LCD DSI OTM8009A, cảm ứng FT6206 chu kỳ 40 ms)
 */

#include <stdint.h>
#include <stdbool.h>
#include "stm32f469xx.h"
#include "stm32f4xx_hal.h"
#include "rtos/rtos_types.h"
#include "ui.h"
#include "touch.h"

/* Định nghĩa chân LED trên STM32F469I-DISCO (Active LOW) */
/* LED1: PG6, LED2: PD4, LED3: PD5, LED4: PK3 */
#define LED1_PIN              (6UL)
#define LED2_PIN              (4UL)
#define LED3_PIN              (5UL)
#define LED4_PIN              (3UL)

/* Định nghĩa chân nút bấm USER (Active HIGH) - WAKEUP: PA0 */
#define BUTTON_PIN            (0UL)

/* Dung lượng hàng đợi sự kiện */
